                className="group relative flex flex-col rounded-2xl border border-[var(--hairline)] bg-[var(--surface-2)]/20 p-5 shadow-sm transition-all"
              >
                <div className="flex items-center justify-between border-b border-[var(--hairline)] pb-3 mb-3">
                  <div className="flex items-center gap-2">
                    <div
                      className={`h-2 w-2 rounded-full ${pg.status === "active" ? "bg-green-500" : "bg-yellow-500"}`}
                    />
                    <h3 className="font-bold text-sm text-foreground">
                      {pg.post_name || "Provisioning..."}
                    </h3>
                  </div>
                  <span className="text-[10px] uppercase font-semibold text-muted-foreground tracking-wider bg-white/[0.04] px-2 py-0.5 rounded-full">
                    {pg.type || "Unknown"}
                  </span>
                </div>

                <div className="space-y-2 text-xs text-muted-foreground">
                  <div className="flex items-center justify-between">
                    <span className="font-medium">User ID:</span>
                    <span className="truncate max-w-[120px]">{pg.userid}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="font-medium">Context:</span>
                    <span>{pg.from}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="font-medium">IP:</span>
                    <span className="font-mono text-indigo-400">{pg.ip || "Assigning..."}</span>
                  </div>
                  {pg.start && (
                    <div className="flex items-center justify-between pt-2 border-t border-[var(--hairline)]">
                      <span className="font-medium flex items-center gap-1.5">
                        <Clock className="h-3 w-3" /> Uptime:
                      </span>
                      <span>{Math.floor((Date.now() - pg.start) / 60000)} mins</span>
                    </div>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {/* Playground form modal */}
      {isFormOpen && (
        <CreateConfigModal
          isOpen={isFormOpen}
          onClose={() => setIsFormOpen(false)}
          onSuccess={() => {
            void queryClient.invalidateQueries({ queryKey: ["admin", "templates"] });
            toast.success("Profile created successfully!");
          }}
        />
      )}

      {/* Edit config modal */}
      {isEditModalOpen && selectedConfig && (
        <EditConfigModal
          isOpen={isEditModalOpen}
          onClose={() => {
            setIsEditModalOpen(false);
            setSelectedConfig(null);
          }}
          onSuccess={() => {
            void queryClient.invalidateQueries({ queryKey: ["admin", "templates"] });
            toast.success("Profile updated successfully!");
          }}
          config={selectedConfig}
        />
      )}
    </div>
  );
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import type { User } from "@/domain/user";
import { UserRole } from "@/domain/auth";
import type { RegisterPayload, OtpPayload } from "@/domain/auth";
import { authService } from "@/infrastructure/auth/authService";
import { setUnauthorizedHandler, tokenStore } from "@/infrastructure/http/apiClient";
import { authStore } from "../hooks/authStore";

export interface AuthState {
  isAuthenticated: boolean;
  isLoading: boolean;
  user: User | null;
  login: (email: string, password: string) => Promise<{ role: UserRole }>;
  logout: () => Promise<void>;
  register: (payload: RegisterPayload) => Promise<{ userId: string }>;
  sendOtp: (payload: OtpPayload) => Promise<{ message: string }>;
  verifyOtp: (payload: OtpPayload & { otp: string }) => Promise<{ message: string }>;
}

// Exported so hooks/useAuth.ts can import it directly.
export const AuthContext = createContext<AuthState | null>(null);

function normalizeRole(role: string): UserRole {
  const upper = role.toUpperCase();
  if (upper === "ADMIN") return UserRole.ADMIN;
  if (upper === "INSTRUCTOR") return UserRole.INSTRUCTOR;
  return UserRole.STUDENT;
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const bootstrapped = useRef(false);

  const clear = useCallback(() => {
    tokenStore.set(null);
    setUser(null);
  }, []);

  useEffect(() => {
    setUnauthorizedHandler(clear);
    return () => setUnauthorizedHandler(null);
  }, [clear]);

  // Silently restore session on app load using httpOnly refresh cookie.
  useEffect(() => {
    if (bootstrapped.current) return;
    bootstrapped.current = true;
    (async () => {
      try {
        const { accessToken } = await authService.refresh();
        tokenStore.set(accessToken);
        // Validate token and get user id + role from /verify-token.
        const tokenData = await authService.verifyToken();
        // Build a minimal User object from the token payload.
        // Full profile data can be fetched lazily from user-service.
        setUser({
          id: tokenData.user.id,
          email: "",
          name: "",
          role: normalizeRole(tokenData.user.role),
        });
      } catch {
        clear();
      } finally {
        setIsLoading(false);
      }
    })();
  }, [clear]);

  /**
   * Logs the user in. Returns the user's role so the caller can redirect.
   * Throws with the API error code (e.g. "EMAIL_NOT_VERIFIED") on failure.
   */
  const login = useCallback(async (email: string, password: string) => {
    const { accessToken, user: loggedInUser } = await authService.login({ email, password });
    tokenStore.set(accessToken);
    const normalizedUser: User = {
      id: loggedInUser.id,
      email: loggedInUser.email,
      name: loggedInUser.name,
      role: normalizeRole(loggedInUser.role),
      avatarUrl: loggedInUser.avatarUrl,
    };
    setUser(normalizedUser);
    return { role: normalizedUser.role };
  }, []);

  const logout = useCallback(async () => {
    try {
      await authService.logout();
    } finally {
      clear();
    }
  }, [clear]);

  const register = useCallback((payload: RegisterPayload) => authService.register(payload), []);

  const sendOtp = useCallback((payload: OtpPayload) => authService.sendOtp(payload), []);

  const verifyOtp = useCallback(
    (payload: OtpPayload & { otp: string }) => authService.verifyOtp(payload),
    [],
  );

  // Sync to authStore so router beforeLoad guards can read auth state.
  useEffect(() => {
    authStore.set({ isAuthenticated: !!user, isLoading, user });
  }, [user, isLoading]);

  const value = useMemo<AuthState>(
    () => ({
      isAuthenticated: !!user,
      isLoading,
      user,
      login,
      logout,
      register,
      sendOtp,
      verifyOtp,
    }),
    [user, isLoading, login, logout, register, sendOtp, verifyOtp],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

/** @deprecated Import useAuth from "@/presentation/features/auth/hooks/useAuth" instead. */
export function useAuth(): AuthState {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within <AuthProvider>");
  return ctx;
}

/**
 * PlaygroundWorkspace.tsx — Main playground workspace component.
 *
 * Renders the full-height split-pane environment with:
 * - Terminal panel (left/main) with Xterm.js-ready iframe
 * - Optional code-server / desktop GUI iframes
 * - Status overlay during provisioning phases
 * - Automatic cleanup on unmount
 *
 * This component is designed to be embedded within the Student Course Viewer
 * when a chapter of type "PLAYGROUND" is active.
 */

import { memo, useCallback, useRef, useState } from "react";
import {
  TerminalSquare,
  Code,
  Monitor,
  RefreshCcw,
  Square,
  Maximize2,
  Minimize2,
} from "lucide-react";
import type { PlaygroundConfig, TemplateConfig } from "@/domain/playground";
import { usePlaygroundLifecycle } from "../hooks/usePlaygroundLifecycle";
import { PlaygroundStatusOverlay } from "./PlaygroundStatusOverlay";

// ─── Constants ──────────────────────────────────────────────────────────────

const PLAYGROUND_PORT_URL = (import.meta.env.VITE_PORT_URL as string) ?? "";

// ─── Tab Types ──────────────────────────────────────────────────────────────

type ActiveTab = "terminal" | "vscode" | "desktop";

// ─── Props ──────────────────────────────────────────────────────────────────

interface PlaygroundWorkspaceProps {
  /** Playground configuration from the chapter entity. */
  config: PlaygroundConfig;
  /** Origin context: "course" or "challenge". */
  from: string;
  /** ID of the course or challenge. */
  fromId: string;
  /** Callback when the user stops/exits the playground. */
  onStop?: () => void;
  /** Callback for marking the lesson complete. */
  onMarkComplete?: () => void;
  /** Optional: Markdown/document content for split-pane instructions. */
  instructionContent?: string;
}

// ─── Component ──────────────────────────────────────────────────────────────

function PlaygroundWorkspaceInner({ config, from, fromId, onStop }: PlaygroundWorkspaceProps) {
  const { instance, templateConfig, teardown, hasError, retry } = usePlaygroundLifecycle(
    config,
    from,
    fromId,
  );

  const [activeTab, setActiveTab] = useState<ActiveTab>("terminal");
  const [isMaximized, setIsMaximized] = useState(false);

  // Iframe refs for refresh functionality
  const terminalIframeRef = useRef<HTMLIFrameElement>(null);
  const vscodeIframeRef = useRef<HTMLIFrameElement>(null);
  const desktopIframeRef = useRef<HTMLIFrameElement>(null);

  // ── Derived state ─────────────────────────────────────────────────────

  const isReady = instance.phase === "READY";
  const showOverlay = !isReady && instance.phase !== "DESTROYED";
  const hasIDE = templateConfig?.templates.some((t) => t["enable-ide"]) ?? false;
  const hasGUI = templateConfig?.templates.some((t) => t["enable-gui"]) ?? false;

  // ── Handlers ──────────────────────────────────────────────────────────

  const handleStop = useCallback(async () => {
    await teardown();
    onStop?.();
  }, [teardown, onStop]);

  const handleRefresh = useCallback(() => {
    const refs: Record<ActiveTab, React.RefObject<HTMLIFrameElement | null>> = {
      terminal: terminalIframeRef,
      vscode: vscodeIframeRef,
      desktop: desktopIframeRef,
    };
    const iframe = refs[activeTab]?.current;
    if (iframe) {
      iframe.src = iframe.src;
    }
  }, [activeTab]);

  // ── Build iframe URLs ─────────────────────────────────────────────────

  const buildTerminalUrl = () => {
    if (!instance.postName || !PLAYGROUND_PORT_URL) return "";
    return `${location.protocol}//${instance.postName}-terminalprt.${PLAYGROUND_PORT_URL}`;
  };

  const buildVSCodeUrl = () => {
    if (!instance.postName || !PLAYGROUND_PORT_URL) return "";
    return `${location.protocol}//${instance.postName}-codeserverprt.${PLAYGROUND_PORT_URL}`;
  };

  const buildDesktopUrl = () => {
    if (!instance.postName || !PLAYGROUND_PORT_URL) return "";
    return `${location.protocol}//${instance.postName}-desktopprt.${PLAYGROUND_PORT_URL}`;
  };

  // ── Render overlay during provisioning ────────────────────────────────

  if (showOverlay) {
    return <PlaygroundStatusOverlay instance={instance} onRetry={retry} onCancel={onStop} />;
  }

  // ── Main workspace UI ─────────────────────────────────────────────────

  return (
    <div className="flex-1 flex flex-col overflow-hidden bg-background relative">
      {/* ── Toolbar ──────────────────────────────────────────────────── */}
      <div className="flex items-center justify-between h-10 px-2 bg-card border-b border-border shrink-0 select-none">
        {/* Left: Tabs */}
        <div className="flex items-center gap-1 overflow-x-auto">
          {/* Terminal Tab */}
          <TabButton
            icon={<TerminalSquare className="h-3.5 w-3.5" />}
            label="Terminal"
            active={activeTab === "terminal"}
            onClick={() => setActiveTab("terminal")}
          />

          {/* VS Code Tab (conditional) */}
          {hasIDE && (
            <TabButton
              icon={<Code className="h-3.5 w-3.5" />}
              label="VS Code"
              active={activeTab === "vscode"}
              onClick={() => setActiveTab("vscode")}
            />
          )}

          {/* Desktop Tab (conditional) */}
          {hasGUI && (
            <TabButton
              icon={<Monitor className="h-3.5 w-3.5" />}
              label="Desktop"
              active={activeTab === "desktop"}
              onClick={() => setActiveTab("desktop")}
            />
          )}
        </div>

        {/* Right: Actions */}
        <div className="flex items-center gap-1">
          <ActionButton
            icon={<RefreshCcw className="h-3.5 w-3.5" />}
            title="Refresh"
            onClick={handleRefresh}
          />
          <ActionButton
            icon={
              isMaximized ? (
                <Minimize2 className="h-3.5 w-3.5" />
              ) : (
                <Maximize2 className="h-3.5 w-3.5" />
              )
            }
            title={isMaximized ? "Restore" : "Maximize"}
            onClick={() => setIsMaximized(!isMaximized)}
          />
          <div className="h-4 w-px bg-border mx-0.5" />
          <ActionButton
            icon={<Square className="h-3.5 w-3.5" />}
            title="Stop Playground"
            onClick={handleStop}
            danger
          />
        </div>
      </div>

      {/* ── Content Area ──────────────────────────────────────────── */}
      <div className="flex-1 relative overflow-hidden bg-[#0a0a0f]">
        {/* Terminal iframe */}
        <IframePane
          ref={terminalIframeRef}
          src={buildTerminalUrl()}
          visible={activeTab === "terminal"}
          title="Terminal"
        />

        {/* VS Code iframe */}
        {hasIDE && (
          <IframePane
            ref={vscodeIframeRef}
            src={buildVSCodeUrl()}
            visible={activeTab === "vscode"}
            title="VS Code"
          />
        )}

        {/* Desktop iframe */}
        {hasGUI && (
          <IframePane
            ref={desktopIframeRef}
            src={buildDesktopUrl()}
            visible={activeTab === "desktop"}
            title="Desktop GUI"
          />
        )}
      </div>
    </div>
  );
}

// ─── Sub-components ─────────────────────────────────────────────────────────

function TabButton({
  icon,
  label,
  active,
  onClick,
}: {
  icon: React.ReactNode;
  label: string;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold rounded-lg border transition-all ${
        active
          ? "bg-primary/20 border-primary/30 text-primary shadow-[0_0_12px_-3px_var(--primary-glow)]"
          : "bg-transparent border-transparent text-muted-foreground hover:bg-foreground/5 hover:text-foreground"
      }`}
    >
      {icon}
      <span className="truncate">{label}</span>
    </button>
  );
}

function ActionButton({
  icon,
  title,
  onClick,
  danger = false,
}: {
  icon: React.ReactNode;
  title: string;
  onClick: () => void;
  danger?: boolean;
}) {
  return (
    <button
      onClick={onClick}
      title={title}
      className={`h-7 w-7 flex items-center justify-center rounded-lg transition-all ${
        danger
          ? "text-muted-foreground hover:bg-destructive/20 hover:text-destructive"
          : "text-muted-foreground hover:bg-foreground/5 hover:text-foreground"
      }`}
    >
      {icon}
    </button>
  );
}

import { forwardRef } from "react";

const IframePane = forwardRef<HTMLIFrameElement, { src: string; visible: boolean; title: string }>(
  function IframePane({ src, visible, title }, ref) {
    if (!src) return null;

    return (
      <div
        className="absolute inset-0"
        style={{
          zIndex: visible ? 10 : -1,
          opacity: visible ? 1 : 0,
          pointerEvents: visible ? "auto" : "none",
        }}
      >
        <iframe
          ref={ref}
          src={src}
          title={title}
          className="w-full h-full border-0 bg-[#0a0a0f]"
          allow="clipboard-read; clipboard-write"
          sandbox="allow-same-origin allow-scripts allow-forms allow-popups allow-popups-to-escape-sandbox"
        />
      </div>
    );
  },
);

